// #6a993d791a95398b11e1fb6e — ספריית תבניות סימולציה וסיוע להקמת התרחיש הראשון. Кейсы TPL-004…TPL-008, TPL-010.
// Роли: admin (библиотека, «סיוע») + business (testim: модалка «מתבנית», черновики, запрет записи). Каждая роль — своё окно (asUser).
// Данные: шаблон «QA-AUTO-TPL-<stamp>» и его копия — в afterAll ОТКЛЮЧАЮТСЯ (удаления шаблонов нет).
// Черновики симуляций из шаблона (имя = имя шаблона, QA-AUTO-…) неудаляемы — остаются у testim.
// Генерацию AI-сценария тесты не запускают (только создание черновика и чтение полей).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi, runStamp, Api } from '../support/api';

test.describe.configure({ mode: 'serial' });

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
const BUSINESS_ID = 'd8be531e-92f5-4668-9de5-7f784e1e9014'; // testim — бизнес сессии auth/business.json
const STAMP = runStamp();
const TEMPLATE_NAME = `QA-AUTO-TPL-${STAMP}`;
const GOAL_V1 = `QA-AUTO מטרה גרסה 1 ${STAMP}`;
const GOAL_V2 = `QA-AUTO מטרה גרסה 2 ${STAMP}`;
const TAG = '@desktop @data #6a993d791a95398b11e1fb6e';

let templateId = '';
let copyId = '';
let copyName = '';
let templateFields: Record<string, unknown> = {};
const drafts: string[] = []; // черновики с целью v1 (из «סיוע» и из модалки)

type Sim = { id: string; name: string; status: string; template_id: string | null; call_goal: string | null };

/** Копия полей с новой целью: ищет ключ call_goal на любой глубине. */
function withGoal(fields: Record<string, unknown>, goal: string) {
  let found = false;
  const walk = (v: unknown): unknown => {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') {
      const out: Record<string, unknown> = {};
      for (const [k, val] of Object.entries(v)) {
        if (k === 'call_goal') { out[k] = goal; found = true; } else out[k] = walk(val);
      }
      return out;
    }
    return v;
  };
  const res = walk(fields) as Record<string, unknown>;
  expect(found, 'в полях шаблона нет call_goal').toBeTruthy();
  return res;
}

const simsByName = async (api: Api, name: string) => {
  const res = await api.get(`simulations?select=id,name,status,template_id,call_goal&name=eq.${encodeURIComponent(name)}&order=created_at.asc`);
  expect(res.ok(), `simulations: ${res.status()}`).toBeTruthy();
  return (await res.json()) as Sim[];
};

const assistBlock = (page: Page) => page.getByRole('region', { name: 'סיוע בהקמת התרחיש הראשון' });
const newSimDialog = (page: Page) => page.getByRole('dialog', { name: 'סימולציה חדשה' });

async function setStatus(api: Api, id: string, status: 'active' | 'disabled') {
  const res = await api.rpc('admin_set_template_status', { p_template_id: id, p_status: status });
  expect(res.ok(), `admin_set_template_status ${status}: ${res.status()} ${await res.text()}`).toBeTruthy();
}

test.describe('Шаблоны симуляций — библиотека и סיוע בהקמת התרחיש הראשון (#6a993d791a95398b11e1fb6e)', () => {
  test.afterAll(async ({ browser }) => {
    if (!templateId && !copyId) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE });
    try {
      const api = await openWithApi(await ctx.newPage(), '/admin/templates');
      for (const id of [templateId, copyId].filter(Boolean)) {
        await api.rpc('admin_set_template_status', { p_template_id: id, p_status: 'disabled' });
      }
    } finally {
      await ctx.close();
    }
  });

  test(`admin: шаблон сохраняется как шаблон («פעילה»), а не как симуляция ${TAG}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const api = await openWithApi(admin, '/admin/templates');
    const src = await api.get('simulation_templates?select=id,fields&order=created_at.asc&limit=1');
    expect(src.ok()).toBeTruthy();
    const [source] = (await src.json()) as { fields: Record<string, unknown> }[];
    expect(source, 'нужен хотя бы один шаблон-источник полей').toBeTruthy();
    templateFields = withGoal(source.fields, GOAL_V1);

    const saved = await api.rpc('admin_save_template', { p_template_id: null, p_name: TEMPLATE_NAME, p_fields: templateFields });
    expect(saved.ok(), `admin_save_template: ${saved.status()} ${await saved.text()}`).toBeTruthy();
    const found = await api.get(`simulation_templates?select=id,status&name=eq.${encodeURIComponent(TEMPLATE_NAME)}`);
    const rows = (await found.json()) as { id: string; status: string }[];
    expect(rows).toHaveLength(1);
    templateId = rows[0].id;
    test.info().annotations.push({ type: 'test-data', description: `template ${TEMPLATE_NAME} ${templateId} (отключается в afterAll)` });
    if (rows[0].status !== 'active') await setStatus(api, templateId, 'active');

    // Источник: AC1 — «היא נשמרת כתבנית ולא כסימולציה פעילה».
    await admin.goto('/admin/templates');
    const row = admin.getByRole('row').filter({ hasText: TEMPLATE_NAME });
    await expect(row).toBeVisible();
    await expect(row).toContainText('פעילה');

    const biz = await asUser('business');
    const bizApi = await openWithApi(biz, '/simulations');
    expect(await simsByName(bizApi, TEMPLATE_NAME)).toHaveLength(0);
  });

  test(`admin «סיוע»: сбой — сообщение с повтором без черновика; успех — черновик у бизнеса ${TAG}`, async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const admin = await asUser('admin');
    await admin.goto(`/admin/businesses/${BUSINESS_ID}`);
    const block = assistBlock(admin);
    await expect(block).toBeVisible();
    await block.getByLabel('תבנית סימולציה').selectOption({ label: TEMPLATE_NAME });
    const submit = block.getByRole('button', { name: 'יצירת טיוטה לעסק' });

    // Источник: FL-02 ш.1 — «כשל בהחלת התבנית מציג הודעה עם ניסיון חוזר ואינו יוצר טיוטה חלקית».
    const rpcUrl = '**/rest/v1/rpc/create_simulation_from_template';
    await admin.route(rpcUrl, (r) => r.abort());
    await submit.click();
    await expect(block.getByText('לא בוצע')).toBeVisible();
    await expect(block.getByText('יצירת הטיוטה נכשלה. אפשר לנסות שוב.')).toBeVisible();
    await expect(submit).toBeEnabled();
    await admin.unroute(rpcUrl);

    const biz = await asUser('business');
    const bizApi = await openWithApi(biz, '/simulations');
    expect(await simsByName(bizApi, TEMPLATE_NAME), 'при сбое черновик не создаётся').toHaveLength(0);

    // Источник: דרישה 2 — «החלה של תבנית על עסק ספציפי ... כולל סיוע יזום».
    const applied = admin.waitForResponse((r) => r.url().includes('/rpc/create_simulation_from_template'));
    await submit.click();
    expect((await applied).ok()).toBeTruthy();
    await expect(block.getByText('נוצרה טיוטה מהתבנית')).toBeVisible();
    await expect(block.getByText('נוספה לסימולציות של העסק')).toContainText(TEMPLATE_NAME);

    const sims = await simsByName(bizApi, TEMPLATE_NAME);
    expect(sims).toHaveLength(1);
    expect(sims[0]).toMatchObject({ status: 'draft', template_id: templateId, call_goal: GOAL_V1 });
    drafts.push(sims[0].id);
    test.info().annotations.push({ type: 'test-data', description: `draft (סיוע) ${sims[0].id} (неудаляем)` });

    await biz.goto('/simulations');
    await expect(biz.getByText(TEMPLATE_NAME).first()).toBeVisible();
  });

  test(`business: «סימולציה חדשה» → «מתבנית» → «המשך לעורך» — черновик с полями шаблона, поля редактируемы ${TAG}`, async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const biz = await asUser('business');
    const api = await openWithApi(biz, '/simulations/new');
    const dialog = newSimDialog(biz);
    await expect(dialog).toBeVisible();
    // Источник: FL-11 ш.1 — «נבחר מסלול פתיחה — מאפס או מתבנית»; Figma 774:2522.
    await expect(dialog.getByRole('radio', { name: /^מתבנית/ })).toBeChecked();
    await expect(dialog.getByRole('radio', { name: /^מאפס/ })).toBeVisible();
    await expect(dialog.getByText('תבניות זמינות')).toBeVisible();

    await dialog.getByTestId('use-template').filter({ hasText: TEMPLATE_NAME }).click();
    await dialog.getByRole('button', { name: 'המשך לעורך' }).click();
    await biz.waitForURL(new RegExp(`/simulations/(?!${templateId})[0-9a-f-]{36}`));
    const id = biz.url().match(/\/simulations\/([0-9a-f-]{36})/)![1];
    drafts.push(id);
    test.info().annotations.push({ type: 'test-data', description: `draft (модалка) ${id} (неудаляем)` });

    // Источник: AC2 — «כל שדות התבנית מועתקים לטיוטה חדשה של אותו עסק וניתנים לעריכה מלאה».
    const name = biz.getByLabel(/^שם הסימולציה/);
    const goal = biz.getByLabel(/^מטרת השיחה/);
    await expect(name).toHaveValue(TEMPLATE_NAME);
    await expect(name).toBeEditable();
    await expect(goal).toHaveValue(GOAL_V1);
    await expect(goal).toBeEditable();

    const [sim] = (await (await api.get(`simulations?select=id,name,status,template_id,call_goal&id=eq.${id}`)).json()) as Sim[];
    expect(sim).toMatchObject({ status: 'draft', template_id: templateId, call_goal: GOAL_V1 });
  });

  test(`изменение шаблона не меняет созданные черновики, действует на новые ${TAG}`, async ({ asUser }) => {
    expect(drafts, 'нужны 2 черновика из предыдущих тестов (serial)').toHaveLength(2);
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, '/admin/templates');
    const saved = await adminApi.rpc('admin_save_template', {
      p_template_id: templateId,
      p_name: TEMPLATE_NAME,
      p_fields: withGoal(templateFields, GOAL_V2),
    });
    expect(saved.ok(), `admin_save_template: ${saved.status()} ${await saved.text()}`).toBeTruthy();

    const biz = await asUser('business');
    const api = await openWithApi(biz, '/simulations');
    // Источник: AC4 / דרישה 6 — «סימולציות שכבר נוצרו ממנה אינן משתנות והשינוי חל רק על שימושים עתידיים».
    const before = await simsByName(api, TEMPLATE_NAME);
    for (const id of drafts) expect(before.find((s) => s.id === id)?.call_goal).toBe(GOAL_V1);

    const created = await api.rpc('create_simulation_from_template', { p_template_id: templateId });
    expect(created.ok(), `create_simulation_from_template: ${created.status()} ${await created.text()}`).toBeTruthy();
    const after = await simsByName(api, TEMPLATE_NAME);
    expect(after).toHaveLength(before.length + 1);
    const fresh = after.filter((s) => !before.some((b) => b.id === s.id));
    expect(fresh).toHaveLength(1);
    expect(fresh[0]).toMatchObject({ status: 'draft', template_id: templateId, call_goal: GOAL_V2 });
    test.info().annotations.push({ type: 'test-data', description: `draft (v2) ${fresh[0].id} (неудаляем)` });
    for (const id of drafts) expect(after.find((s) => s.id === id)?.call_goal).toBe(GOAL_V1);
  });

  test(`שכפול и השבתה: копия «מושבתת» не предлагается ни в «סיוע», ни в модалке ${TAG}`, async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const admin = await asUser('admin');
    const api = await openWithApi(admin, '/admin/templates');
    const dup = await api.rpc('admin_duplicate_template', { p_template_id: templateId });
    expect(dup.ok(), `admin_duplicate_template: ${dup.status()} ${await dup.text()}`).toBeTruthy();
    const copies = (await (
      await api.get(`simulation_templates?select=id,name&name=like.${encodeURIComponent(`${TEMPLATE_NAME}*`)}&id=neq.${templateId}`)
    ).json()) as { id: string; name: string }[];
    expect(copies).toHaveLength(1);
    ({ id: copyId, name: copyName } = copies[0]);
    expect(copyName).toContain('עותק');
    test.info().annotations.push({ type: 'test-data', description: `template copy ${copyName} ${copyId} (отключена)` });
    await setStatus(api, copyId, 'disabled');

    // Источник: דרישה 1 — «יצירה, עריכה, שכפול והשבתה של תבניות סימולציה על ידי Super Admin».
    await admin.goto('/admin/templates');
    const copyRow = admin.getByRole('row').filter({ hasText: copyName });
    await expect(copyRow).toContainText('מושבתת');
    await expect(copyRow.getByRole('button', { name: 'הפעלה' })).toBeVisible();

    await admin.goto(`/admin/businesses/${BUSINESS_ID}`);
    const select = assistBlock(admin).getByLabel('תבנית סימולציה');
    await expect(select.getByRole('option', { name: TEMPLATE_NAME, exact: true })).toHaveCount(1);
    await expect(select.getByRole('option', { name: copyName, exact: true })).toHaveCount(0);

    const biz = await asUser('business');
    await biz.goto('/simulations/new');
    const dialog = newSimDialog(biz);
    await expect(dialog.getByTestId('use-template').filter({ hasText: TEMPLATE_NAME }).first()).toBeVisible();
    await expect(dialog.getByText(copyName, { exact: true })).toHaveCount(0);
  });

  test(`business не может править шаблон платформы: 403 в UI, RPC и PATCH — 403, имя не изменилось ${TAG}`, async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const biz = await asUser('business');
    const api = await openWithApi(biz, '/');

    // Источник: FL-02 ш.2 — «נחסם עם הסבר שהתבנית מנוהלת ברמת הפלטפורמה».
    await biz.goto('/admin/templates');
    await expect(biz.getByText('קוד 403')).toBeVisible();
    await expect(biz.getByText('אין לכם גישה לעמוד הזה')).toBeVisible();
    await expect(biz.getByText(/המסך הזה מנוהל ברמת הפלטפורמה על ידי צוות המערכת, וכך גם תבניות הסימולציה/)).toBeVisible();
    await expect(biz.getByRole('link', { name: 'חזרה לדשבורד' })).toBeVisible();
    await expect(biz.getByRole('link', { name: 'פנייה לתמיכה' })).toBeVisible();
    await expect(biz.getByRole('button', { name: 'תבנית חדשה' })).toHaveCount(0);
    await expect(biz.getByText(TEMPLATE_NAME)).toHaveCount(0);

    // Источник: AC5 — «הפעולה נחסמת והוא רשאי רק לצרוך אותה».
    const probe = `${TEMPLATE_NAME}-API-PROBE`;
    const rpc = await api.rpc('admin_save_template', { p_template_id: templateId, p_name: probe, p_fields: templateFields });
    expect(rpc.status()).toBe(403);
    expect(await rpc.text()).toContain('42501');
    const patch = await api.patch(`simulation_templates?id=eq.${templateId}`, { name: probe });
    expect(patch.status()).toBe(403);
    expect(await patch.text()).toContain('42501');

    const read = await api.get(`simulation_templates?select=name&id=eq.${templateId}`);
    expect(read.status()).toBe(200);
    expect(((await read.json()) as { name: string }[])[0]?.name).toBe(TEMPLATE_NAME);
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, '/admin/templates');
    const adminRead = (await (await adminApi.get(`simulation_templates?select=name&id=eq.${templateId}`)).json()) as { name: string }[];
    expect(adminRead[0]?.name).toBe(TEMPLATE_NAME);
  });
});
